using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // Breaking change #1 – EF Core 9 renamed "Discriminator" to "$type".
            // Existing 500K documents use "Discriminator"; keep reading/writing that
            // property so existing docs and raw SQL queries stay compatible.
            entity.HasDiscriminator<string>("Discriminator");

            // Breaking change #2 – EF Core 9 no longer prepends the entity type to
            // the id value (was "Product|123", now just "123").
            // Preserve the old format so existing documents remain addressable.
            entity.HasPartitionKey(p => p.Id);
            entity.Property(p => p.Id)
                  .HasConversion(
                      id => $"Product|{id}",
                      stored => int.Parse(stored.Replace("Product|", "")));
        });
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

